-- DURGA SAMITI DATABASE: Supabase SQL Editor-এ সম্পূর্ণ কোড একবার RUN করুন
create extension if not exists pgcrypto with schema extensions;
create table if not exists public.durga_members(member_id text primary key check(member_id ~ '^[0-9]{10}$'),name text not null,created_at timestamptz not null default now());
create table if not exists public.durga_site_data(id integer primary key check(id=1),data jsonb not null default '{"notices":[],"income":0,"expense":0}'::jsonb,updated_at timestamptz not null default now());
create table if not exists public.durga_settings_secret(id integer primary key check(id=1),password_hash text not null);
alter table public.durga_members enable row level security; alter table public.durga_site_data enable row level security; alter table public.durga_settings_secret enable row level security;
drop policy if exists "public read member directory" on public.durga_members; create policy "public read member directory" on public.durga_members for select to anon,authenticated using(true);
drop policy if exists "public read samiti data" on public.durga_site_data; create policy "public read samiti data" on public.durga_site_data for select to anon,authenticated using(true);
revoke all on public.durga_members from anon,authenticated; grant select on public.durga_members to anon,authenticated; revoke all on public.durga_site_data from anon,authenticated; grant select on public.durga_site_data to anon,authenticated; revoke all on public.durga_settings_secret from anon,authenticated;
insert into public.durga_members(name,member_id) values ('আকাশ কর্মকার','9002907513'),('সাঅন দে','8582808581'),('ইন্দ্রজিত কর্মকার','6295738409'),('নতুন সদস্য ৪','7318452096'),('নতুন সদস্য ৫','8462195730'),('নতুন সদস্য ৬','5927301846'),('নতুন সদস্য ৭','4186259037'),('নতুন সদস্য ৮','9631074258'),('নতুন সদস্য ৯','2758496130'),('নতুন সদস্য ১০','6843029175'),('নতুন সদস্য ১১','3509718264'),('নতুন সদস্য ১২','8172640395') on conflict(member_id) do nothing;
insert into public.durga_site_data(id,data) values(1,'{"notices":[],"income":0,"expense":0}'::jsonb) on conflict(id) do nothing;
insert into public.durga_settings_secret(id,password_hash) values(1,extensions.crypt('AK@2026#£',extensions.gen_salt('bf'))) on conflict(id) do nothing;
create or replace function public.durga_check_settings_password(p_password text) returns boolean language sql security definer set search_path=public,extensions as $$ select exists(select 1 from public.durga_settings_secret where id=1 and password_hash=extensions.crypt(p_password,password_hash)); $$;
create or replace function public.durga_save_all(p_password text,p_members jsonb,p_data jsonb) returns boolean language plpgsql security definer set search_path=public,extensions as $$ declare ok boolean; begin select exists(select 1 from public.durga_settings_secret where id=1 and password_hash=extensions.crypt(p_password,password_hash)) into ok; if not ok then return false; end if; if jsonb_typeof(p_members)<>'array' or jsonb_typeof(p_data)<>'object' then raise exception 'Invalid data'; end if; if exists(select 1 from jsonb_to_recordset(p_members) as x(name text,member_id text) where coalesce(trim(name),'')='' or member_id !~ '^[0-9]{10}$') then raise exception 'Member name and 10 digit ID required'; end if; if (select count(*) from jsonb_to_recordset(p_members) as x(name text,member_id text))<>(select count(distinct member_id) from jsonb_to_recordset(p_members) as x(name text,member_id text)) then raise exception 'Duplicate Member ID'; end if; delete from public.durga_members; insert into public.durga_members(name,member_id) select trim(name),member_id from jsonb_to_recordset(p_members) as x(name text,member_id text); insert into public.durga_site_data(id,data,updated_at) values(1,p_data,now()) on conflict(id) do update set data=excluded.data,updated_at=now(); return true; end; $$;
revoke all on function public.durga_check_settings_password(text) from public; revoke all on function public.durga_save_all(text,jsonb,jsonb) from public; grant execute on function public.durga_check_settings_password(text) to anon,authenticated; grant execute on function public.durga_save_all(text,jsonb,jsonb) to anon,authenticated;
do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='durga_members') then alter publication supabase_realtime add table public.durga_members; end if; if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='durga_site_data') then alter publication supabase_realtime add table public.durga_site_data; end if; end $$;
-- সতর্কতা: নাম+ID শক্ত পরিচয় যাচাই নয়। Settings password জানা যে কেউ সব তথ্য সম্পাদনা করতে পারবে।
